  // (and their payments) and move on.
  if (BigInt(blocks.length) !== to - from + 1n) return fail('INVALID_RESPONSE');
  for (let i = 0; i < blocks.length; i++) {
    if ((blocks[i] as TronBlock).number !== from + BigInt(i)) return fail('INVALID_RESPONSE');
  }
  return blocks;
